// Secure Express.js application with comprehensive security measures

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const expressValidator = require('express-validator');
const cors = require('cors');
const morgan = require('morgan');
const app = express();

// Security Configuration
// =======================

// 1. Security Headers (Helmet.js)
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            scriptSrc: ["'self'"],
            styleSrc: ["'self'"],
            imgSrc: ["'self'"],
            connectSrc: ["'self'"],
            fontSrc: ["'self'"],
            objectSrc: ["'none'"],
            mediaSrc: ["'self'"],
            frameSrc: ["'none'"]
        }
    },
    hidePoweredBy: true,
    hsts: {
        maxAge: 31536000,
        includeSubDomains: true,
        preload: true
    },
    noSniff: true,
    xssFilter: true,
    frameguard: {
        action: 'deny'
    }
}));

// 2. Rate Limiting
const apiLimiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(apiLimiter);

// 3. CORS Configuration
const corsOptions = {
    origin: process.env.NODE_ENV === 'production' 
        ? ['https://yourdomain.com'] // Production domains
        : ['http://localhost:3000'], // Development
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true,
    maxAge: 86400
};
app.use(cors(corsOptions));

// 4. Request Parsing with Limits
app.use(express.json({
    limit: '1mb' // Prevent large payload attacks
}));
app.use(express.urlencoded({
    extended: true,
    limit: '1mb'
}));

// 5. Request Validation Middleware
const { body, query, param, validationResult } = require('express-validator');

// 6. Security Logging
app.use(morgan('combined', {
    skip: (req, res) => req.path === '/health' // Skip health checks
}));

// 7. Custom Security Headers
app.use((req, res, next) => {
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('X-Frame-Options', 'DENY');
    res.setHeader('X-XSS-Protection', '1; mode=block');
    res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
    res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
    next();
});

// Route Definitions with Security
// ===============================

// Health endpoint with minimal logging
app.get('/health', (req, res) => {
    res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        service: 'secure-api'
    });
});

// Secure Users endpoint with input validation
app.get('/users', 
    // Input validation
    query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),

    // Authentication middleware (example - implement based on your auth system)
    // authenticateToken,

    // Authorization middleware (example)
    // authorize('read', 'users'),

    (req, res) => {
        // Check validation results
        const errors = validationResult(req);
        if (!errors.isEmpty()) {
            return res.status(400).json({ 
                errors: errors.array(),
                message: 'Validation failed'
            });
        }

        // Pagination support with limits
        const page = parseInt(req.query.page) || 1;
        const limit = parseInt(req.query.limit) || 10;
        const offset = (page - 1) * limit;

        // In a real application, this would come from a database with proper access control
        const mockUsers = [
            { 
                id: 1, 
                name: 'Alice', 
                email: 'alice@example.com',
                role: 'user'
            },
            { 
                id: 2, 
                name: 'Bob', 
                email: 'bob@example.com',
                role: 'admin'
            },
        ];

        // Secure response - remove sensitive data based on user role
        const sanitizedUsers = mockUsers.map(user => ({
            id: user.id,
            name: user.name,
            // Email is only included for authenticated users in real implementation
            // In production, implement proper authorization checks
            email: user.email
        }));

        res.json({
            users: sanitizedUsers,
            pagination: {
                page,
                limit,
                total: mockUsers.length,
                pages: Math.ceil(mockUsers.length / limit)
            }
        });
});

// Error Handling Middleware
app.use((err, req, res, next) => {
    console.error('Security Event:', {
        timestamp: new Date().toISOString(),
        path: req.path,
        method: req.method,
        ip: req.ip,
        userAgent: req.get('User-Agent'),
        error: err.message
    });

    // Don't expose error details in production
    const errorResponse = process.env.NODE_ENV === 'production' 
        ? { 
            message: 'An error occurred',
            errorId: Date.now() // For correlation with logs
          }
        : { 
            message: err.message,
            stack: err.stack 
          };

    res.status(err.status || 500).json(errorResponse);
});

// 404 Handler - Don't leak information about missing routes
app.use((req, res) => {
    res.status(404).json({
        message: 'Resource not found'
    });
});

// Environment Configuration Check
const requiredEnvVars = ['NODE_ENV', 'PORT'];
const missingEnvVars = requiredEnvVars.filter(varName => !process.env[varName]);

if (missingEnvVars.length > 0 && process.env.NODE_ENV === 'production') {
    console.error('Missing required environment variables:', missingEnvVars);
    process.exit(1);
}

const PORT = process.env.PORT || 3000;

// Graceful shutdown handling
const server = app.listen(PORT, () => {
    console.log(`Secure server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);

    // Security audit log
    console.log('Security Features Enabled:', {
        helmet: true,
        rateLimiting: true,
        cors: true,
        inputValidation: true,
        securityHeaders: true,
        errorHandling: true
    });
});

// Graceful shutdown
process.on('SIGTERM', () => {
    console.log('SIGTERM received. Starting graceful shutdown...');
    server.close(() => {
        console.log('Server closed gracefully');
        process.exit(0);
    });
});

process.on('SIGINT', () => {
    console.log('SIGINT received. Starting graceful shutdown...');
    server.close(() => {
        console.log('Server closed gracefully');
        process.exit(0);
    });
});

module.exports = app;

