/**
 * Secure Secrets Management Configuration
 * Provides multiple layers of secrets protection
 */

const fs = require('fs');
const path = require('path');

class SecretsManager {
  constructor() {
    this.loadedSecrets = new Map();
    this.initialized = false;
    this.canaryTokens = new Set();
  }

  /**
   * Initialize secrets manager with multiple fallback sources
   */
  async initialize() {
    if (this.initialized) return;

    try {
      // Priority 1: Environment variables (Docker/Cloud Native)
      this.loadFromEnvironment();

      // Priority 2: External secrets manager (AWS Secrets Manager, HashiCorp Vault, etc.)
      await this.loadFromExternalSecretsManager();

      // Priority 3: Local .env file (development only)
      if (process.env.NODE_ENV === 'development') {
        this.loadFromDotenv();
      }

      // Priority 4: Default/fallback values
      this.setDefaults();

      // Validate all required secrets
      this.validateSecrets();

      // Setup canary token monitoring
      this.setupCanaryMonitoring();

      this.initialized = true;
      console.log('Secrets manager initialized successfully');
    } catch (error) {
      console.error('Failed to initialize secrets manager:', error.message);
      throw error;
    }
  }

  /**
   * Load from environment variables
   */
  loadFromEnvironment() {
    const requiredSecrets = [
      'JWT_SECRET',
      'SESSION_SECRET',
      'DATABASE_URL',
      'REDIS_URL'
    ];

    const optionalSecrets = [
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY',
      'LOGFIRE_TOKEN'
    ];

    // Load required secrets
    for (const secretName of requiredSecrets) {
      const value = process.env[secretName];
      if (!value && process.env.NODE_ENV === 'production') {
        throw new Error(`Required secret ${secretName} not found in environment`);
      }
      if (value) {
        this.loadedSecrets.set(secretName, value);
      }
    }

    // Load optional secrets
    for (const secretName of optionalSecrets) {
      const value = process.env[secretName];
      if (value) {
        this.loadedSecrets.set(secretName, value);
        this.checkForCanaryToken(secretName, value);
      }
    }
  }

  /**
   * Load from external secrets manager (AWS Secrets Manager example)
   */
  async loadFromExternalSecretsManager() {
    // Only use external manager in production
    if (process.env.NODE_ENV !== 'production') {
      return;
    }

    try {
      // AWS Secrets Manager integration example
      if (process.env.AWS_SECRETS_MANAGER_ENABLED === 'true') {
        await this.loadFromAWSSecretsManager();
      }

      // HashiCorp Vault integration example
      if (process.env.VAULT_ENABLED === 'true') {
        await this.loadFromVault();
      }

      // Azure Key Vault integration example
      if (process.env.AZURE_KEY_VAULT_ENABLED === 'true') {
        await this.loadFromAzureKeyVault();
      }
    } catch (error) {
      console.warn('External secrets manager unavailable:', error.message);
    }
  }

  /**
   * Example: AWS Secrets Manager integration
   */
  async loadFromAWSSecretsManager() {
    // In production, you would use:
    // const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

    console.log('Loading secrets from AWS Secrets Manager...');

    // Mock implementation - replace with actual AWS SDK calls
    const mockSecrets = {
      'production/database': JSON.stringify({
        DATABASE_URL: process.env.DATABASE_URL
      }),
      'production/api-keys': JSON.stringify({
        JWT_SECRET: process.env.JWT_SECRET,
        SESSION_SECRET: process.env.SESSION_SECRET
      })
    };

    // Parse and load mock secrets
    for (const [secretId, secretString] of Object.entries(mockSecrets)) {
      try {
        const secrets = JSON.parse(secretString);
        for (const [key, value] of Object.entries(secrets)) {
          this.loadedSecrets.set(key, value);
        }
      } catch (error) {
        console.error(`Failed to parse secret ${secretId}:`, error.message);
      }
    }
  }

  /**
   * Load from .env file (development only)
   */
  loadFromDotenv() {
    try {
      const dotenv = require('dotenv');
      const envPath = path.resolve(process.cwd(), '.env');

      if (fs.existsSync(envPath)) {
        const result = dotenv.config({ path: envPath });

        if (result.error) {
          console.warn('Failed to load .env file:', result.error.message);
        } else {
          console.log('Loaded secrets from .env file');

          // Check for canary tokens in .env file
          for (const [key, value] of Object.entries(result.parsed || {})) {
            this.checkForCanaryToken(key, value);
          }
        }
      }
    } catch (error) {
      console.warn('dotenv not available or failed to load:', error.message);
    }
  }

  /**
   * Set default values for development
   */
  setDefaults() {
    if (process.env.NODE_ENV !== 'production') {
      const defaults = {
        JWT_SECRET: 'development-jwt-secret-change-in-production',
        SESSION_SECRET: 'development-session-secret-change-in-production',
        DATABASE_URL: 'postgres://localhost:5432/development',
        REDIS_URL: 'redis://localhost:6379'
      };

      for (const [key, value] of Object.entries(defaults)) {
        if (!this.loadedSecrets.has(key)) {
          this.loadedSecrets.set(key, value);
          console.warn(`Using default value for ${key} - NOT FOR PRODUCTION`);
        }
      }
    }
  }

  /**
   * Validate all required secrets
   */
  validateSecrets() {
    const validationRules = {
      JWT_SECRET: (value) => value.length >= 32,
      SESSION_SECRET: (value) => value.length >= 32,
      DATABASE_URL: (value) => value.startsWith('postgres://') || value.startsWith('mysql://'),
      AWS_ACCESS_KEY_ID: (value) => value.startsWith('AKIA') || value.includes('CANARY'),
      STRIPE_SECRET_KEY: (value) => value.startsWith('sk_') || value.includes('CANARY')
    };

    for (const [secretName, validator] of Object.entries(validationRules)) {
      const value = this.loadedSecrets.get(secretName);
      if (value && !validator(value)) {
        console.warn(`Secret ${secretName} failed validation check`);
      }
    }
  }

  /**
   * Check for canary tokens in secrets
   */
  checkForCanaryToken(secretName, value) {
    const canaryPatterns = [
      /CANARY-/i,
      /test-secret/i,
      /example-/i,
      /placeholder/i,
      /changeme/i,
      /your-/i
    ];

    for (const pattern of canaryPatterns) {
      if (pattern.test(value)) {
        this.canaryTokens.add(secretName);
        console.warn(`CANARY TOKEN DETECTED: ${secretName} contains test/placeholder value`);

        // In production, this would trigger an alert
        if (process.env.NODE_ENV === 'production') {
          this.alertCanaryToken(secretName, value);
        }
        break;
      }
    }
  }

  /**
   * Alert on canary token detection
   */
  alertCanaryToken(secretName, value) {
    // Integrate with your alerting system (PagerDuty, Slack, etc.)
    console.error(`PRODUCTION CANARY ALERT: Secret ${secretName} contains test value!`);

    // Log to security monitoring system
    const securityEvent = {
      type: 'CANARY_TOKEN_DETECTED',
      timestamp: new Date().toISOString(),
      secret: secretName,
      environment: process.env.NODE_ENV,
      severity: 'HIGH'
    };

    // Send to security monitoring
    // Example: Send to Logfire, Datadog, Splunk, etc.
    this.logSecurityEvent(securityEvent);
  }

  /**
   * Log security events
   */
  logSecurityEvent(event) {
    // Integrate with your security monitoring system
    console.log('SECURITY_EVENT:', event);

    // Example: Send to external monitoring
    // if (this.loadedSecrets.has('LOGFIRE_TOKEN')) {
    //   // Send to Logfire
    // }
  }

  /**
   * Setup canary token monitoring
   */
  setupCanaryMonitoring() {
    // Monitor for canary token usage
    setInterval(() => {
      if (this.canaryTokens.size > 0) {
        console.warn(`Active canary tokens: ${Array.from(this.canaryTokens).join(', ')}`);
      }
    }, 3600000); // Check every hour
  }

  /**
   * Get a secret value
   */
  get(secretName) {
    if (!this.initialized) {
      throw new Error('Secrets manager not initialized. Call initialize() first.');
    }

    const value = this.loadedSecrets.get(secretName);

    if (!value) {
      throw new Error(`Secret ${secretName} not found`);
    }

    // Log secret access (without revealing value)
    this.logSecretAccess(secretName);

    return value;
  }

  /**
   * Log secret access for audit trail
   */
  logSecretAccess(secretName) {
    const auditLog = {
      timestamp: new Date().toISOString(),
      secret: secretName,
      accessedBy: 'application',
      environment: process.env.NODE_ENV,
      ip: 'internal'
    };

    // Log to audit system
    console.log('SECRET_ACCESS:', auditLog);
  }

  /**
   * Rotate a secret (example method)
   */
  async rotateSecret(secretName) {
    console.log(`Rotating secret: ${secretName}`);

    // Generate new secret
    const newSecret = this.generateSecureSecret();

    // Update in external secrets manager
    await this.updateExternalSecret(secretName, newSecret);

    // Update locally
    this.loadedSecrets.set(secretName, newSecret);

    return newSecret;
  }

  /**
   * Generate secure secret
   */
  generateSecureSecret() {
    return require('crypto').randomBytes(32).toString('hex');
  }

  /**
   * Update secret in external manager
   */
  async updateExternalSecret(secretName, newValue) {
    // Implement based on your secrets manager
    console.log(`Updating ${secretName} in external secrets manager`);
    // Actual implementation depends on AWS Secrets Manager, HashiCorp Vault, etc.
  }

  /**
   * Get all loaded secret names (without values)
   */
  listSecrets() {
    return Array.from(this.loadedSecrets.keys());
  }

  /**
   * Check if a secret exists
   */
  has(secretName) {
    return this.loadedSecrets.has(secretName);
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

module.exports = {
  secretsManager,
  SecretsManager
};

/**
 * Secure Application Entry Point
 * Proper secrets management and environment configuration
 */

// Load environment variables BEFORE any other imports
require('dotenv').config();
require('dotenv-expand').expand(require('dotenv').config());

const { secretsManager } = require('./secrets-config');
const app = require('./app-secure');

// Initialize secrets manager with proper error handling
async function initializeApplication() {
  console.log('Initializing secure application...');

  try {
    // Step 1: Initialize secrets manager
    await secretsManager.initialize();

    // Step 2: Validate environment
    validateEnvironment();

    // Step 3: Configure application with secrets
    configureApplication();

    // Step 4: Start server
    startServer();

  } catch (error) {
    console.error('Failed to initialize application:', error.message);
    console.error('Stack trace:', error.stack);
    process.exit(1);
  }
}

/**
 * Validate runtime environment
 */
function validateEnvironment() {
  const nodeEnv = process.env.NODE_ENV || 'development';
  console.log(`Running in ${nodeEnv} environment`);

  // Environment-specific validations
  switch (nodeEnv) {
    case 'production':
      validateProductionEnvironment();
      break;

    case 'staging':
      validateStagingEnvironment();
      break;

    case 'development':
      validateDevelopmentEnvironment();
      break;

    default:
      console.warn(`Unknown NODE_ENV: ${nodeEnv}`);
  }
}

/**
 * Validate production environment
 */
function validateProductionEnvironment() {
  console.log('Validating production environment...');

  const requiredSecrets = [
    'JWT_SECRET',
    'SESSION_SECRET',
    'DATABASE_URL'
  ];

  const missingSecrets = [];

  for (const secret of requiredSecrets) {
    if (!secretsManager.has(secret)) {
      missingSecrets.push(secret);
    }
  }

  if (missingSecrets.length > 0) {
    throw new Error(`Missing required secrets in production: ${missingSecrets.join(', ')}`);
  }

  // Check for canary tokens in production (should not exist)
  const loadedSecrets = secretsManager.listSecrets();
  const canaryPatterns = [/CANARY-/i, /test-/i, /example-/i];

  for (const secretName of loadedSecrets) {
    const value = secretsManager.get(secretName);
    for (const pattern of canaryPatterns) {
      if (pattern.test(value)) {
        throw new Error(`CANARY TOKEN IN PRODUCTION: ${secretName} contains test value`);
      }
    }
  }

  console.log('✅ Production environment validation passed');
}

/**
 * Validate staging environment
 */
function validateStagingEnvironment() {
  console.log('Validating staging environment...');

  const warnings = [];

  // Check for production-like secrets in staging
  const productionPatterns = [
    /sk_live_/i,      // Live Stripe keys
    /prod\./i,        // Production database URLs
    /live\./i,        // Live service URLs
    /production/i     // Production indicators
  ];

  const loadedSecrets = secretsManager.listSecrets();

  for (const secretName of loadedSecrets) {
    const value = secretsManager.get(secretName);
    for (const pattern of productionPatterns) {
      if (pattern.test(value)) {
        warnings.push(`${secretName} appears to contain production value`);
        break;
      }
    }
  }

  if (warnings.length > 0) {
    console.warn('Staging environment warnings:');
    warnings.forEach(warning => console.warn(`  ⚠️  ${warning}`));
  }

  console.log('✅ Staging environment validation passed with warnings');
}

/**
 * Validate development environment
 */
function validateDevelopmentEnvironment() {
  console.log('Validating development environment...');

  // Warn about default/placeholder secrets
  const defaultSecrets = [
    'development-jwt-secret-change-in-production',
    'development-session-secret-change-in-production'
  ];

  const loadedSecrets = secretsManager.listSecrets();

  for (const secretName of loadedSecrets) {
    const value = secretsManager.get(secretName);
    if (defaultSecrets.includes(value)) {
      console.warn(`⚠️  ${secretName} is using default development value`);
    }
  }

  console.log('✅ Development environment validation passed');
}

/**
 * Configure application with secrets
 */
function configureApplication() {
  console.log('Configuring application with secrets...');

  // Set global configuration from secrets
  global.appConfig = {
    jwtSecret: secretsManager.get('JWT_SECRET'),
    sessionSecret: secretsManager.get('SESSION_SECRET'),
    databaseUrl: secretsManager.get('DATABASE_URL'),
    redisUrl: secretsManager.get('REDIS_URL'),
    environment: process.env.NODE_ENV || 'development',

    // Optional external service keys
    awsAccessKeyId: secretsManager.has('AWS_ACCESS_KEY_ID') 
      ? secretsManager.get('AWS_ACCESS_KEY_ID') 
      : null,

    awsSecretAccessKey: secretsManager.has('AWS_SECRET_ACCESS_KEY') 
      ? secretsManager.get('AWS_SECRET_ACCESS_KEY') 
      : null,

    stripeSecretKey: secretsManager.has('STRIPE_SECRET_KEY') 
      ? secretsManager.get('STRIPE_SECRET_KEY') 
      : null,

    anthropicApiKey: secretsManager.has('ANTHROPIC_API_KEY') 
      ? secretsManager.get('ANTHROPIC_API_KEY') 
      : null,

    logfireToken: secretsManager.has('LOGFIRE_TOKEN') 
      ? secretsManager.get('LOGFIRE_TOKEN') 
      : null
  };

  // Log configuration (without revealing sensitive values)
  console.log('Application configuration:', {
    environment: global.appConfig.environment,
    databaseConfigured: !!global.appConfig.databaseUrl,
    redisConfigured: !!global.appConfig.redisUrl,
    externalServices: {
      aws: !!global.appConfig.awsAccessKeyId,
      stripe: !!global.appConfig.stripeSecretKey,
      anthropic: !!global.appConfig.anthropicApiKey,
      logfire: !!global.appConfig.logfireToken
    }
  });
}

/**
 * Start the server
 */
function startServer() {
  const PORT = process.env.PORT || 3000;

  app.listen(PORT, () => {
    console.log(`🚀 Secure server running on port ${PORT}`);
    console.log(`📊 Environment: ${process.env.NODE_ENV || 'development'}`);
    console.log(`🔐 Secrets loaded: ${secretsManager.listSecrets().length}`);
    console.log(`🌐 Health endpoint: http://localhost:${PORT}/health`);

    // Security audit log
    logSecurityAudit();
  });
}

/**
 * Log security audit information
 */
function logSecurityAudit() {
  const auditInfo = {
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    nodeVersion: process.version,
    platform: process.platform,
    secretsSource: determineSecretsSource(),
    securityFeatures: {
      helmet: true,
      rateLimiting: true,
      cors: true,
      inputValidation: true,
      secretsManager: true
    }
  };

  console.log('🔒 Security Audit:', auditInfo);
}

/**
 * Determine where secrets are loaded from
 */
function determineSecretsSource() {
  if (process.env.AWS_SECRETS_MANAGER_ENABLED === 'true') {
    return 'AWS Secrets Manager';
  } else if (process.env.VAULT_ENABLED === 'true') {
    return 'HashiCorp Vault';
  } else if (process.env.AZURE_KEY_VAULT_ENABLED === 'true') {
    return 'Azure Key Vault';
  } else if (process.env.KUBERNETES_SECRETS_ENABLED === 'true') {
    return 'Kubernetes Secrets';
  } else {
    return process.env.NODE_ENV === 'production' 
      ? 'Environment Variables' 
      : '.env file';
  }
}

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('UNCAUGHT EXCEPTION:', error.message);
  console.error('Stack trace:', error.stack);

  // Don't expose error details in production
  if (process.env.NODE_ENV === 'production') {
    console.error('Application error - check logs for details');
  }

  // Graceful shutdown
  setTimeout(() => process.exit(1), 1000);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('UNHANDLED REJECTION at:', promise);
  console.error('Reason:', reason);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  process.exit(0);
});

// Initialize the application
initializeApplication();

module.exports = {
  initializeApplication,
  validateEnvironment,
  configureApplication
};

