// Secure Express.js Application
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
require('dotenv').config();

const app = express();

// ========== SECURITY MIDDLEWARE ==========
// 1. Helmet for security headers
app.use(helmet());

// 2. CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : [],
  optionsSuccessStatus: 200,
  credentials: true
};
app.use(cors(corsOptions));

// 3. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP
  message: { error: 'Too many requests from this IP, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false
});
app.use(limiter);

// 4. Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Custom security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});

// ========== AUTHENTICATION MIDDLEWARE ==========
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // In production, use JWT verification
  // jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
  //   if (err) return res.status(403).json({ error: 'Invalid token' });
  //   req.user = user;
  //   next();
  // });

  // Simple token check for example
  if (token === process.env.API_TOKEN) {
    next();
  } else {
    res.status(403).json({ error: 'Invalid token' });
  }
};

// ========== VALIDATION UTILITIES ==========
const validateUserId = (req, res, next) => {
  const { id } = req.params;
  if (id && !/^\d+$/.test(id)) {
    return res.status(400).json({ error: 'User ID must be a number' });
  }
  next();
};

// ========== ROUTES ==========
// Public route (no authentication)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: '1.0.0'
  });
});

// Protected routes
app.get('/users', authenticateToken, (req, res) => {
  // In production, fetch from database with proper access control
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com',
      createdAt: '2024-01-01T00:00:00.000Z'
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com',
      createdAt: '2024-01-02T00:00:00.000Z'
    },
  ];

  // Hide sensitive fields if needed
  const safeUsers = users.map(user => ({
    id: user.id,
    name: user.name,
    createdAt: user.createdAt
  }));

  res.json(safeUsers);
});

app.get('/users/:id', authenticateToken, validateUserId, (req, res) => {
  const userId = parseInt(req.params.id);

  // In production, validate user access to this resource
  // Check if req.user.id === userId or req.user.role === 'admin'

  res.json({
    id: userId,
    name: 'User ' + userId,
    message: 'User details endpoint - implement proper database query'
  });
});

// ========== ERROR HANDLING ==========
// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Server error:', err);

  // Don't leak error details in production
  const errorResponse = process.env.NODE_ENV === 'production' 
    ? { error: 'Internal server error' }
    : { error: err.message, stack: err.stack };

  res.status(500).json(errorResponse);
});

// ========== SERVER STARTUP ==========
const port = process.env.PORT || 3000;
const nodeEnv = process.env.NODE_ENV || 'development';

// Ensure required environment variables are set
if (!process.env.API_TOKEN && nodeEnv === 'production') {
  console.error('ERROR: API_TOKEN environment variable is required in production');
  process.exit(1);
}

app.listen(port, () => {
  console.log(`✅ Server running in ${nodeEnv} mode on port ${port}`);
  console.log(`📁 Health check: http://localhost:${port}/health`);
});

module.exports = app;

# Essential Security Packages for Express.js

## **Core Security Packages**

### **1. Helmet.js - Security Headers**
```bash
npm install helmet
```
```javascript
const helmet = require('helmet');
app.use(helmet());
```

### **2. Express Rate Limit - Brute Force Protection**
```bash
npm install express-rate-limit
```
```javascript
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use(limiter);
```

### **3. Express Validator - Input Validation**
```bash
npm install express-validator
```
```javascript
const { body, validationResult } = require('express-validator');
app.post('/user', 
  body('email').isEmail(),
  body('password').isLength({ min: 8 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
  }
);
```

### **4. CORS - Cross-Origin Resource Sharing**
```bash
npm install cors
```
```javascript
const cors = require('cors');
app.use(cors({
  origin: ['https://yourdomain.com'],
  credentials: true
}));
```

### **5. JWT - Authentication**
```bash
npm install jsonwebtoken
npm install bcrypt
```
```javascript
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');

// Generate token
const token = jwt.sign({ userId: user.id }, process.env.JWT_SECRET, {
  expiresIn: '1h'
});

// Hash password
const hashedPassword = await bcrypt.hash(password, 10);
```

### **6. DOMPurify - XSS Protection**
```bash
npm install dompurify
npm install jsdom
```
```javascript
const createDOMPurify = require('dompurify');
const { JSDOM } = require('jsdom');
const window = new JSDOM('').window;
const DOMPurify = createDOMPurify(window);

const cleanHTML = DOMPurify.sanitize(userInput);
```

### **7. csurf - CSRF Protection**
```bash
npm install csurf
```
```javascript
const csrf = require('csurf');
const csrfProtection = csrf({ cookie: true });
app.use(csrfProtection);
```

### **8. express-mongo-sanitize - NoSQL Injection Protection**
```bash
npm install express-mongo-sanitize
```
```javascript
const mongoSanitize = require('express-mongo-sanitize');
app.use(mongoSanitize());
```

### **9. hpp - HTTP Parameter Pollution Protection**
```bash
npm install hpp
```
```javascript
const hpp = require('hpp');
app.use(hpp());
```

### **10. express-session - Secure Session Management**
```bash
npm install express-session
```
```javascript
const session = require('express-session');
app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: process.env.NODE_ENV === 'production',
    httpOnly: true,
    maxAge: 1000 * 60 * 60 * 24 // 24 hours
  }
}));
```

## **Development Security Tools**

### **1. ESLint Security Plugin**
```bash
npm install eslint-plugin-security --save-dev
```
```javascript
// .eslintrc.js
module.exports = {
  plugins: ['security'],
  rules: {
    'security/detect-buffer-noassert': 'error',
    'security/detect-child-process': 'error',
    'security/detect-disable-mustache-escape': 'error',
    'security/detect-eval-with-expression': 'error',
    'security/detect-no-csrf-before-method-override': 'error',
    'security/detect-non-literal-fs-filename': 'error',
