class SecretLoader {
  constructor(options = {}) {
    this.options = {
      envFile: '.env',
      exampleFile: '.env.example',
      secretsManager: null, // 'aws', 'azure', 'vault', null for env vars
      failOnMissing: true,
      cacheSecrets: true,
      ...options
    };

    this.secrets = {};
    this.isLoaded = false;
    this.isProduction = process.env.NODE_ENV === 'production';
  }

  /**
   * Load secrets from appropriate source
   */
  async load() {
    if (this.isLoaded && this.options.cacheSecrets) {
      return this.secrets;
    }

    try {
      // Step 1: Try to load from .env for development
      if (!this.isProduction) {
        await this.loadFromEnvFile();
      }

      // Step 2: Load from environment (takes precedence for production)
      this.loadFromEnvironment();

      // Step 3: Load from secrets manager if configured
      if (this.options.secretsManager && this.isProduction) {
        await this.loadFromSecretsManager();
      }

      // Step 4: Validate all required secrets
      this.validateSecrets();

      this.isLoaded = true;
      console.log('✅ Secrets loaded successfully');
      return this.secrets;
    } catch (error) {
      console.error('❌ Failed to load secrets:', error.message);
      if (this.options.failOnMissing) {
        process.exit(1);
      }
      throw error;
    }
  }

  /**
   * Load from .env file with validation
   */
  async loadFromEnvFile() {
    const envPath = path.resolve(process.cwd(), this.options.envFile);
    const examplePath = path.resolve(process.cwd(), this.options.exampleFile);

    // Check if .env file exists
    if (!fs.existsSync(envPath)) {
      console.warn(`⚠️  ${this.options.envFile} file not found`);
      return;
    }

    // Check if .env.example exists for validation
    if (!fs.existsSync(examplePath)) {
      console.warn(`⚠️  ${this.options.exampleFile} file not found, cannot validate`);
      return;
    }

    // Use dotenv-safe if available
    try {
      const dotenvSafe = require('dotenv-safe');
      dotenvSafe.config({
        path: envPath,
        example: examplePath,
        allowEmptyValues: false
      });
    } catch (error) {
      console.warn('⚠️  dotenv-safe not available, falling back to dotenv');
      require('dotenv').config({ path: envPath });
    }
  }

  /**
   * Load from environment variables
   */
  loadFromEnvironment() {
    const secretPatterns = [
      /_SECRET$/,
      /_KEY$/,
      /_TOKEN$/,
      /_PASSWORD$/,
      /DATABASE_URL$/,
      /CONNECTION_STRING$/
    ];

    // Load all environment variables that look like secrets
    for (const [key, value] of Object.entries(process.env)) {
      if (value && secretPatterns.some(pattern => pattern.test(key))) {
        this.secrets[key] = value;
      }
    }

    // Also load explicitly defined secrets
    const explicitSecrets = [
      'JWT_SECRET',
      'API_TOKEN',
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY'
    ];

    for (const key of explicitSecrets) {
      if (process.env[key]) {
        this.secrets[key] = process.env[key];
      }
    }
  }

  /**
   * Load from secrets manager (AWS Secrets Manager example)
   */
  async loadFromSecretsManager() {
    switch (this.options.secretsManager) {
      case 'aws':
        await this.loadFromAWSSecretsManager();
        break;
      case 'azure':
        await this.loadFromAzureKeyVault();
        break;
      case 'vault':
        await this.loadFromHashiCorpVault();
        break;
      default:
        console.warn(`Unknown secrets manager: ${this.options.secretsManager}`);
    }
  }

  async loadFromAWSSecretsManager() {
    try {
      const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

      const client = new SecretsManagerClient({
        region: process.env.AWS_REGION || 'us-east-1'
      });

      const secretName = process.env.SECRETS_NAME || 'app/production/secrets';

      console.log(`🔐 Loading secrets from AWS Secrets Manager: ${secretName}`);

      const response = await client.send(
        new GetSecretValueCommand({ SecretId: secretName })
      );

      if (response.SecretString) {
        const secrets = JSON.parse(response.SecretString);
        Object.assign(this.secrets, secrets);
      }
    } catch (error) {
      console.error('Failed to load from AWS Secrets Manager:', error.message);
      throw error;
    }
  }

  async loadFromAzureKeyVault() {
    // Implementation for Azure Key Vault
    console.warn('Azure Key Vault integration not implemented');
  }

  async loadFromHashiCorpVault() {
    // Implementation for HashiCorp Vault
    console.warn('HashiCorp Vault integration not implemented');
  }

  /**
   * Validate required secrets exist
   */
  validateSecrets() {
    const requiredSecrets = this.getRequiredSecrets();
    const missing = [];

    for (const secret of requiredSecrets) {
      if (!this.secrets[secret] && !process.env[secret]) {
        missing.push(secret);
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }

  /**
   * Get list of required secrets based on environment
   */
  getRequiredSecrets() {
    const baseSecrets = ['JWT_SECRET', 'API_TOKEN'];

    if (this.isProduction) {
      return [...baseSecrets, 'DATABASE_URL'];
    }

    return baseSecrets;
  }

  /**
   * Get a secret value
   */
  get(key, defaultValue = null) {
    // First check cached secrets
    if (key in this.secrets) {
      return this.secrets[key];
    }

    // Then check environment
    if (process.env[key]) {
      return process.env[key];
    }

    // Return default or throw
    if (defaultValue !== null) {
      return defaultValue;
    }

    throw new Error(`Secret not found: ${key}`);
  }

  /**
   * Get all secrets (for debugging/auditing)
   */
  getAll(maskSecrets = true) {
    if (maskSecrets) {
      const masked = {};
      for (const [key, value] of Object.entries(this.secrets)) {
        if (value && typeof value === 'string') {
          masked[key] = this.maskSecret(value);
        } else {
          masked[key] = value;
        }
      }
      return masked;
    }

    return { ...this.secrets };
  }

  /**
   * Mask secret for safe logging
   */
  maskSecret(secret) {
    if (!secret || typeof secret !== 'string') return secret;

    if (secret.length <= 8) {
      return '***';
    }

    return secret.substring(0, 2) + '***' + secret.substring(secret.length - 2);
  }

  /**
   * Clear secrets from memory (for security)
   */
  clear() {
    for (const key of Object.keys(this.secrets)) {
      this.secrets[key] = null;
    }
    this.secrets = {};
    this.isLoaded = false;
  }
}

// Singleton instance
const secretLoader = new SecretLoader({
  secretsManager: process.env.SECRETS_MANAGER || null,
  failOnMissing: process.env.NODE_ENV === 'production'
});

// Export both class and instance
module.exports = {
  SecretLoader,
  secretLoader
};

// Usage example (if run directly)
if (require.main === module) {
  (async () => {
    try {
      const secrets = await secretLoader.load();
      console.log('Loaded secrets:', secretLoader.getAll(true));

      // Test getting secrets
      console.log('JWT_SECRET:', secretLoader.maskSecret(secretLoader.get('JWT_SECRET', 'not set')));
      console.log('API_TOKEN:', secretLoader.maskSecret(secretLoader.get('API_TOKEN', 'not set')));
    } catch (error) {
      console.error(error);
      process.exit(1);
    }
  })();
}

