      };

      const user = validUsers[username];

      if (!user || user.password !== password) {
        return res.status(401).json({ error: 'Invalid credentials' });
      }

      // Create JWT token using secret
      const token = jwt.sign(
        { id: user.id, role: user.role, username },
        config.jwtSecret,
        { expiresIn: '1h' }
      );

