        user: { id: user.id, role: user.role, username },
        expiresIn: '1h'
      });
    });

    // ========== ERROR HANDLING ==========

    // 404 handler
    app.use((req, res) => {
      res.status(404).json({ error: 'Route not found' });
    });

    // Global error handler
    app.use((err, req, res, next) => {
      console.error('Server error:', err);

      // Don't leak error details in production
      const errorResponse = config.nodeEnv === 'production' 
        ? { error: 'Internal server error' }
        : { 
            error: err.message, 
            stack: err.stack,
            // Mask any secrets that might appear in error messages
            message: err.message ? err.message.replace(config.jwtSecret, '[JWT_SECRET]') : err.message
          };

      res.status(500).json(errorResponse);
    });

