// Secure Express.js Application - Security Review Implementation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// ========== SECURITY CONFIGURATION ==========

// 1. Security Headers (OWASP A05:2021)
app.use(helmet());

// 2. Rate Limiting (DoS Protection)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP'
});
app.use(limiter);

// 3. Body Parsing with Limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 4. Custom Security Headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

// ========== AUTHENTICATION MIDDLEWARE (OWASP A07:2021) ==========

const authenticateToken = (req, res, next) => {
  // Simple token-based authentication for example
  // In production, use JWT or session-based authentication
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Validate token (simplified for example)
  if (token === 'valid-token') {
    req.user = { id: 1, role: 'user' };
    next();
  } else {
    res.status(403).json({ error: 'Invalid token' });
  }
};

// ========== INPUT VALIDATION MIDDLEWARE (OWASP A03:2021) ==========

const validateUserRequest = [
  body('name').notEmpty().trim().escape(),
  body('email').isEmail().normalizeEmail()
];

// ========== SECURE ROUTES ==========

// Public health endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    message: 'Service is healthy'
  });
});

// Protected users endpoint (OWASP A01:2021 - Access Control)
app.get('/users', authenticateToken, (req, res) => {
  // Return only necessary fields (OWASP A03:2021 - Information Exposure)
  const users = [
    { id: 1, name: 'Alice' }, // Email removed for privacy
    { id: 2, name: 'Bob' },
  ];

  res.json(users);
});

// User creation with input validation
app.post('/users', authenticateToken, validateUserRequest, (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { name, email } = req.body;

  // Process validated input
  res.status(201).json({
    id: 3,
    name,
    email, // Email only returned to authenticated users
    message: 'User created successfully'
  });
});

// Get user by ID with parameter validation
app.get('/users/:id', authenticateToken, (req, res) => {
  const userId = parseInt(req.params.id);

  // Validate ID parameter (OWASP A03:2021 - Injection Protection)
  if (isNaN(userId) || userId <= 0) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }

  // Check authorization (user can only access their own data unless admin)
  if (req.user.id !== userId && req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Access denied' });
  }

  res.json({
    id: userId,
    name: `User ${userId}`,
    message: 'User details'
  });
});

// ========== ERROR HANDLING ==========

// 404 Handler
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

// Global Error Handler
app.use((err, req, res, next) => {
  console.error('Server error:', err);

  // Don't expose error details in production
  const errorResponse = process.env.NODE_ENV === 'production'
    ? { error: 'Internal server error' }
    : { error: err.message };

  res.status(500).json(errorResponse);
});

// ========== SERVER CONFIGURATION ==========

const port = process.env.PORT || 3000;

app.listen(port, () => {
  console.log(`Secure server running on port ${port}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

