/**
 * Secure Secrets Manager for Production Applications
 * 
 * DO NOT COMMIT TO VERSION CONTROL
 * 
 * Features:
 * 1. Hierarchical secret loading (local → AWS → Vault)
 * 2. Encryption at rest
 * 3. Secret rotation support
 * 4. Access logging
 * 5. Environment-specific configurations
 */

const crypto = require('crypto');

class SecretsManager {
  constructor() {
    this.secrets = new Map();
    this.accessLog = [];
    this.initialized = false;
  }

  /**
   * Initialize secrets with hierarchical loading strategy
   */
  async init() {
    if (this.initialized) return;

    console.log('🔐 Initializing secure secrets manager...');

    // Determine environment
    const env = process.env.NODE_ENV || 'development';

    // Order of precedence for secret loading:
    // 1. AWS Secrets Manager (production)
    // 2. HashiCorp Vault (production)
    // 3. Kubernetes Secrets (production)
    // 4. Encrypted local file (development/test)
    // 5. Environment variables (development)
    // 6. .env file (development - last resort)

    try {
      switch (env) {
        case 'production':
          await this.loadFromAwsSecretsManager();
          break;
        case 'staging':
          await this.loadFromVault();
          break;
        case 'test':
          await this.loadFromEncryptedFile('.secrets.test.enc');
          break;
        default: // development
          await this.loadFromEncryptedFile('.secrets.dev.enc')
            .catch(() => this.loadFromEnvFile('.env.development'));
      }

      this.validateRequiredSecrets();
      this.initialized = true;
      console.log('✅ Secrets manager initialized successfully');

    } catch (error) {
      console.error('❌ Failed to initialize secrets manager:', error.message);
      // Don't crash in development
      if (env === 'production') throw error;
    }
  }

  /**
   * Load secrets from AWS Secrets Manager (production)
   */
  async loadFromAwsSecretsManager() {
    console.log('📦 Loading secrets from AWS Secrets Manager...');

    // In production, use AWS SDK
    // For now, simulate with environment variables
    const secretNames = [
      'database/credentials',
      'api/keys',
      'external-services'
    ];

    for (const secretName of secretNames) {
      const envVar = `AWS_SECRET_${secretName.replace(/[\/-]/g, '_').toUpperCase()}`;
      if (process.env[envVar]) {
        const secretValue = this.decrypt(process.env[envVar]);
        this.secrets.set(secretName, JSON.parse(secretValue));
        this.logAccess('aws', secretName, 'read');
      }
    }
  }

  /**
   * Load from HashiCorp Vault (staging)
   */
  async loadFromVault() {
    console.log('🏦 Loading secrets from HashiCorp Vault...');
    // Implementation would use vault client
    // For now, load from environment
    this.loadFromEnv();
  }

  /**
   * Load from encrypted local file (development/test)
   */
  async loadFromEncryptedFile(filename) {
    const fs = require('fs').promises;
    const path = require('path');

    console.log(`🔒 Loading secrets from encrypted file: ${filename}`);

    try {
      const encrypted = await fs.readFile(path.join(__dirname, filename), 'utf8');
      const decrypted = this.decrypt(encrypted);
      const secrets = JSON.parse(decrypted);

      for (const [key, value] of Object.entries(secrets)) {
        this.secrets.set(key, value);
        this.logAccess('encrypted-file', key, 'read');
      }

    } catch (error) {
      throw new Error(`Failed to load encrypted secrets: ${error.message}`);
    }
  }

  /**
   * Load from environment variables
   */
  loadFromEnv() {
    console.log('🌍 Loading secrets from environment variables...');

    const secretPatterns = [
      /_SECRET$/i,
      /_KEY$/i,
      /_TOKEN$/i,
      /_PASSWORD$/i,
      /DATABASE_URL$/i,
      /API_KEYS$/i
    ];

    for (const [key, value] of Object.entries(process.env)) {
      if (secretPatterns.some(pattern => pattern.test(key)) && value) {
        this.secrets.set(key.toLowerCase(), value);
        this.logAccess('env', key, 'read');
      }
    }
  }

  /**
   * Load from .env file (development fallback)
   */
  async loadFromEnvFile(filename = '.env') {
    console.log(`📄 Loading secrets from ${filename}...`);

    try {
      require('dotenv').config({ path: filename });
      this.loadFromEnv();
    } catch (error) {
      console.warn(`⚠️  Could not load ${filename}: ${error.message}`);
    }
  }

  /**
   * Get a secret value
   */
  get(key, defaultValue = null) {
    if (!this.initialized) {
      throw new Error('Secrets manager not initialized. Call init() first.');
    }

    const value = this.secrets.get(key.toLowerCase()) || defaultValue;

    if (!value && defaultValue === null) {
      const error = new Error(`Secret not found: ${key}`);
      error.code = 'SECRET_NOT_FOUND';
      throw error;
    }

    this.logAccess('app', key, 'get');
    return value;
  }

  /**
   * Get database configuration
   */
  getDatabaseConfig() {
    const dbUrl = this.get('database_url');
    if (dbUrl) {
      try {
        const url = new URL(dbUrl);
        return {
          host: url.hostname,
          port: url.port || 5432,
          database: url.pathname.substring(1),
          username: url.username,
          password: url.password,
          ssl: process.env.NODE_ENV === 'production'
        };
      } catch (error) {
        console.warn('Failed to parse DATABASE_URL:', error.message);
      }
    }

    // Fallback to individual config
    return {
      host: this.get('db_host', 'localhost'),
      port: this.get('db_port', 5432),
      database: this.get('db_name', 'app_db'),
      username: this.get('db_user', 'app_user'),
      password: this.get('db_password'),
      ssl: process.env.NODE_ENV === 'production'
    };
  }

  /**
   * Get API keys as array
   */
  getApiKeys() {
    const apiKeys = this.get('api_keys');
    if (apiKeys) {
      return apiKeys.split(',').map(key => key.trim());
    }
    return [];
  }

  /**
   * Rotate a secret (placeholder for actual rotation logic)
   */
  async rotateSecret(key) {
    console.log(`🔄 Rotating secret: ${key}`);
    this.logAccess('rotation', key, 'rotate');

    // In production, this would:
    // 1. Generate new secret
    // 2. Update in secret store
    // 3. Update in memory
    // 4. Notify services
    // 5. Keep old secret temporarily

    return true;
  }

  /**
   * Validate that all required secrets are present
   */
  validateRequiredSecrets() {
    const required = ['api_keys', 'jwt_secret'];
    const missing = [];

    for (const secret of required) {
      if (!this.secrets.has(secret)) {
        missing.push(secret);
      }
    }

    if (missing.length > 0) {
      if (process.env.NODE_ENV === 'production') {
        throw new Error(`Missing required secrets: ${missing.join(', ')}`);
      } else {
        console.warn(`⚠️  Missing recommended secrets: ${missing.join(', ')}`);
      }
    }
  }

  /**
   * Decrypt a value (in production, use KMS or similar)
   */
  decrypt(encrypted) {
    // For development/testing only!
    // In production, use AWS KMS, Azure Key Vault, etc.
    if (process.env.NODE_ENV === 'production') {
      throw new Error('Direct decryption not allowed in production');
    }

    // Simple XOR "encryption" for demonstration
    // DO NOT USE IN PRODUCTION
    const key = process.env.ENCRYPTION_KEY || 'dev-key-change-me';
    let result = '';
    for (let i = 0; i < encrypted.length; i++) {
      result += String.fromCharCode(encrypted.charCodeAt(i) ^ key.charCodeAt(i % key.length));
    }
    return result;
  }

  /**
   * Encrypt a value (in production, use KMS or similar)
   */
  encrypt(plaintext) {
    // For development/testing only!
    if (process.env.NODE_ENV === 'production') {
      throw new Error('Direct encryption not allowed in production');
    }

    const key = process.env.ENCRYPTION_KEY || 'dev-key-change-me';
    let result = '';
    for (let i = 0; i < plaintext.length; i++) {
      result += String.fromCharCode(plaintext.charCodeAt(i) ^ key.charCodeAt(i % key.length));
    }
    return result;
  }

  /**
   * Log all secret accesses for audit
   */
  logAccess(source, key, action) {
    const entry = {
      timestamp: new Date().toISOString(),
      source,
      key,
      action,
      environment: process.env.NODE_ENV || 'development',
      ip: process.env.HOSTNAME || 'localhost'
    };

    this.accessLog.push(entry);

    // Log to console in development
    if (process.env.NODE_ENV !== 'production') {
      console.log(`[Secret Access] ${action.toUpperCase()} ${key} from ${source}`);
    }
  }

  /**
   * Get access log (for audit purposes)
   */
  getAccessLog() {
    return [...this.accessLog];
  }

  /**
   * Clear access log (use with caution)
   */
  clearAccessLog() {
    this.accessLog = [];
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

// Export initialization function
module.exports = {
  init: () => secretsManager.init(),
  get: (key, defaultValue) => secretsManager.get(key, defaultValue),
  getDatabaseConfig: () => secretsManager.getDatabaseConfig(),
  getApiKeys: () => secretsManager.getApiKeys(),
  rotateSecret: (key) => secretsManager.rotateSecret(key),
  getAccessLog: () => secretsManager.getAccessLog(),
  clearAccessLog: () => secretsManager.clearAccessLog()
};

#!/usr/bin/env node
/**
 * Generate encrypted secret files for development
 * 
 * Usage:
 *   node generate-secrets.js --env development
 *   node generate-secrets.js --env test --interactive
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

class SecretGenerator {
  constructor(env = 'development') {
    this.env = env;
    this.encryptionKey = this.generateEncryptionKey();
    this.secrets = {};
  }

  generateEncryptionKey() {
    // Generate a random encryption key
    return crypto.randomBytes(32).toString('hex');
  }

  encrypt(data) {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-gcm', Buffer.from(this.encryptionKey, 'hex'), iv);

    let encrypted = cipher.update(JSON.stringify(data), 'utf8', 'hex');
    encrypted += cipher.final('hex');

    const authTag = cipher.getAuthTag().toString('hex');

    return {
      iv: iv.toString('hex'),
      encrypted,
      authTag,
      algorithm: 'aes-256-gcm'
    };
  }

  generateSecrets() {
    if (this.env === 'production') {
      console.error('⚠️  Never generate production secrets locally!');
      console.error('   Use AWS Secrets Manager, HashiCorp Vault, or similar.');
      process.exit(1);
    }

    // Base secrets for all environments
    this.secrets = {
      // Authentication
      jwt_secret: this.generateRandomString(64),
      session_secret: this.generateRandomString(64),
      api_keys: [
        `dev-api-key-${this.generateRandomString(16)}`,
        `backup-api-key-${this.generateRandomString(16)}`
      ].join(','),

      // Database
      database_url: `postgres://app_user:${this.generateRandomString(32)}@localhost:5432/${this.env}_db`,

      // Rate limiting
      rate_limit_window: '15m',
      rate_limit_max: '100',

      // External services (placeholder values)
      aws_access_key_id: `AKIA${this.generateRandomString(16)}`,
      aws_secret_access_key: this.generateRandomString(40),
      stripe_secret_key: `sk_test_${this.generateRandomString(48)}`,

      // Logging
      log_level: this.env === 'test' ? 'error' : 'debug'
    };

    // Environment-specific additions
    if (this.env === 'test') {
      this.secrets.test_database_url = `postgres://test_user:${this.generateRandomString(32)}@localhost:5432/test_db`;
      this.secrets.allow_unsafe_operations = 'false';
    }

    return this.secrets;
  }

  generateRandomString(length) {
    return crypto.randomBytes(Math.ceil(length / 2))
      .toString('hex')
      .slice(0, length);
  }

  async saveEncryptedSecrets() {
    const encrypted = this.encrypt(this.secrets);
    const filename = `.secrets.${this.env}.enc`;

    fs.writeFileSync(
      path.join(__dirname, filename),
      JSON.stringify(encrypted, null, 2)
    );

    console.log(`✅ Encrypted secrets saved to: ${filename}`);

    // Save encryption key to .env file for development
    if (this.env !== 'production') {
      const envFile = `.env.${this.env}`;
      const envContent = `ENCRYPTION_KEY=${this.encryptionKey}\nNODE_ENV=${this.env}\n`;

      fs.writeFileSync(path.join(__dirname, envFile), envContent);
      console.log(`🔑 Encryption key saved to: ${envFile}`);
      console.log(`⚠️  IMPORTANT: Add ${envFile} to .gitignore!`);
    }

    return { encryptedFile: filename, encryptionKey: this.encryptionKey };
  }

  async savePlaintextSecrets() {
    const filename = `.secrets.${this.env}.json`;

    fs.writeFileSync(
      path.join(__dirname, filename),
      JSON.stringify(this.secrets, null, 2)
    );

    console.log(`📄 Plaintext secrets saved to: ${filename}`);
    console.log(`⚠️  WARNING: Plaintext secrets should NEVER be committed!`);

    return filename;
  }
}

async function main() {
  const args = process.argv.slice(2);
  let env = 'development';
  let interactive = false;
  let plaintext = false;

  // Parse command line arguments
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--env' && args[i + 1]) {
      env = args[i + 1];
      i++;
    } else if (args[i] === '--interactive') {
      interactive = true;
    } else if (args[i] === '--plaintext') {
      plaintext = true;
    } else if (args[i] === '--help') {
      console.log(`
Usage: node generate-secrets.js [options]

Options:
  --env <environment>    Environment (development, test, staging) - default: development
  --interactive          Interactive mode for setting specific values
  --plaintext            Save plaintext JSON file (DANGEROUS - development only)
  --help                 Show this help message

Examples:
  node generate-secrets.js --env development
  node generate-secrets.js --env test --interactive
  node generate-secrets.js --env staging --plaintext
      `);
      process.exit(0);
    }
  }

  console.log(`🔐 Generating secrets for environment: ${env}`);
  console.log('='.repeat(50));

  const generator = new SecretGenerator(env);

  if (interactive) {
    console.log('\n💬 Interactive Mode');
    console.log('Leave blank to use generated value or enter custom value.\n');

    const secrets = generator.generateSecrets();

    for (const [key, defaultValue] of Object.entries(secrets)) {
      await new Promise((resolve) => {
        rl.question(`${key} [${defaultValue}]: `, (answer) => {
          if (answer.trim()) {
            secrets[key] = answer.trim();
          }
          resolve();
        });
      });
    }

    generator.secrets = secrets;
  } else {
    generator.generateSecrets();
  }

  console.log('\n📋 Generated Secrets Summary:');
  console.log('-'.repeat(30));
  for (const [key, value] of Object.entries(generator.secrets)) {
    const displayValue = key.includes('secret') || key.includes('key') || key.includes('password')
      ? `${value.substring(0, 8)}...${value.substring(value.length - 4)}`
      : value;
    console.log(`${key}: ${displayValue}`);
  }

  console.log('\n💾 Saving secrets...');

  if (plaintext && env !== 'production') {
    const plainFile = await generator.savePlaintextSecrets();
    console.log(`\n⚠️  WARNING: Plaintext file created: ${plainFile}`);
    console.log('   This file MUST be added to .gitignore immediately!');
    console.log('   Consider deleting it after encryption.');
  }

  const result = await generator.saveEncryptedSecrets();

  console.log('\n🎉 Success! Next steps:');
  console.log('1. Add the following to .gitignore:');
  console.log(`   - .secrets.${env}.enc`);
  console.log(`   - .env.${env}`);
  console.log('   - .secrets.*.json');
  console.log('2. In your app, use:');
  console.log(`   const secrets = require('./secrets-manager');`);
  console.log(`   await secrets.init();`);
  console.log('3. Access secrets with:');
  console.log(`   const apiKey = secrets.get('api_keys');`);

  rl.close();
}

// Handle Ctrl+C
process.on('SIGINT', () => {
  console.log('\n\n⚠️  Secret generation cancelled.');
  rl.close();
  process.exit(0);
});

if (require.main === module) {
  main().catch(console.error);
}

module.exports = SecretGenerator;

