  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Content Security Policy (adjust as needed for your app)
  res.setHeader('Content-Security-Policy', "default-src 'self'");

  // Referrer policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // Permissions-Policy
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=()');

  next();
});

// Rate limiting (consider using express-rate-limit package)
const rateLimitStore = new Map();
app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();
  const windowMs = 15 * 60 * 1000; // 15 minutes
  const maxRequests = 100;

  if (!rateLimitStore.has(ip)) {
    rateLimitStore.set(ip, { count: 1, startTime: now });
  } else {
    const requestData = rateLimitStore.get(ip);
    if (now - requestData.startTime > windowMs) {
      requestData.count = 1;
      requestData.startTime = now;
    } else {
      requestData.count++;
    }

    if (requestData.count > maxRequests) {
      return res.status(429).json({ error: 'Too many requests' });
    }
  }

  // Clean up old entries periodically (in production, use Redis or similar)
  if (Math.random() < 0.01) { // ~1% of requests
    for (const [key, value] of rateLimitStore.entries()) {
      if (now - value.startTime > windowMs) {
        rateLimitStore.delete(key);
      }
    }
  }

  next();
});

