      if (typeof value === 'string') {
        req.query[key] = value.replace(/[<>"'`]/g, '');
      }
    }
  }

  // Sanitize path parameters
  if (req.params) {
    for (const [key, value] of Object.entries(req.params)) {
      if (typeof value === 'string') {
        req.params[key] = value.replace(/[<>"'`]/g, '');
      }
    }
  }

  next();
};

app.get('/health', validateAndSanitizeInput, (req, res) => {
  // Validate query parameters if any
  if (req.query.detailed) {
    const detailed = req.query.detailed.toLowerCase();
    if (!['true', 'false', 'yes', 'no'].includes(detailed)) {
      return res.status(400).json({ error: 'Invalid detailed parameter' });
    }
  }

  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Simple authentication middleware (in production, use proper auth like JWT/OAuth)
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const token = authHeader.substring(7);

  // In production, validate the token properly
  if (token !== 'valid-token') {
    return res.status(403).json({ error: 'Invalid token' });
  }

  next();
};

app.get('/users', validateAndSanitizeInput, authenticate, (req, res) => {
  // Validate and sanitize any query parameters
  const limit = parseInt(req.query.limit) || 10;
  const offset = parseInt(req.query.offset) || 0;

  if (limit > 100) {
    return res.status(400).json({ error: 'Limit cannot exceed 100' });
  }

  if (offset < 0) {
    return res.status(400).json({ error: 'Offset cannot be negative' });
  }

  // Return paginated data (in production, fetch from database)
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
    { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
  ];

  const paginatedUsers = allUsers.slice(offset, offset + limit);

  // Remove sensitive data based on user role
  const sanitizedUsers = paginatedUsers.map(user => {
    const sanitized = { id: user.id, name: user.name };
    // Only include email for authenticated users (add role-based logic as needed)
    if (req.headers['x-user-role'] === 'admin') {
      sanitized.email = user.email;
      sanitized.role = user.role;
    }
    return sanitized;
  });

  res.json({
    data: sanitizedUsers,
    pagination: {
      limit,
      offset,
      total: allUsers.length
    }
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(`[${new Date().toISOString()}] Error:`, {
    method: req.method,
    url: req.url,
    ip: req.ip,
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  // Don't leak stack traces in production
  const response = {
    error: 'An unexpected error occurred'
  };

  if (process.env.NODE_ENV === 'development') {
    response.details = err.message;
  }

  res.status(500).json(response);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

