#!/usr/bin/env node
/**
 * Secure Secret Generation Script
 * 
 * Usage:
 *   node scripts/generate-secrets.js
 *   node scripts/generate-secrets.js --env production
 *   node scripts/generate-secrets.js --count 5
 */

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

// Command line arguments
const args = process.argv.slice(2);
const env = args.includes('--env') ? args[args.indexOf('--env') + 1] : 'development';
const count = args.includes('--count') ? parseInt(args[args.indexOf('--count') + 1]) : 1;
const outputFile = args.includes('--output') ? args[args.indexOf('--output') + 1] : null;

/**
 * Generate a cryptographically secure random string
 * @param {number} length - Length of the secret in bytes
 * @returns {string} Hex-encoded random string
 */
function generateSecret(length = 32) {
  return crypto.randomBytes(length).toString('hex');
}

/**
 * Generate a set of secrets for an environment
 * @param {string} environment - Environment name
 * @returns {Object} Generated secrets
 */
function generateEnvironmentSecrets(environment) {
  const timestamp = new Date().toISOString();

  return {
    environment,
    generated_at: timestamp,
    secrets: {
      // Core application secrets (64 characters each)
      SESSION_SECRET: generateSecret(32), // 64 hex chars
      JWT_SECRET: generateSecret(32),     // 64 hex chars

      // API tokens (different lengths for different services)
      API_TOKEN: generateSecret(24),      // 48 hex chars
      REFRESH_TOKEN_SECRET: generateSecret(32),

      // Database credentials (example format)
      DB_PASSWORD: generateSecret(16),    // 32 hex chars

      // Special format tokens
      STRIPE_SECRET_KEY: `sk_${generateSecret(24)}`,
      STRIPE_WEBHOOK_SECRET: `whsec_${generateSecret(32)}`,
    }
  };
}

/**
 * Format secrets for .env file
 * @param {Object} secrets - Secrets object
 * @returns {string} .env formatted string
 */
function formatEnvFile(secrets) {
  let output = `# Auto-generated secrets for ${secrets.environment} environment\n`;
  output += `# Generated: ${secrets.generated_at}\n`;
  output += `# DO NOT COMMIT TO VERSION CONTROL\n\n`;

  for (const [key, value] of Object.entries(secrets.secrets)) {
    output += `${key}=${value}\n`;
  }

  return output;
}

/**
 * Format secrets for JSON output
 * @param {Object} secrets - Secrets object
 * @returns {string} JSON formatted string
 */
function formatJsonOutput(secrets) {
  return JSON.stringify(secrets, null, 2);
}

/**
 * Validate that secrets directory exists
 */
function ensureSecretsDir() {
  const secretsDir = path.join(__dirname, '..', 'secrets');
  if (!fs.existsSync(secretsDir)) {
    fs.mkdirSync(secretsDir, { recursive: true });
    console.log(`Created secrets directory: ${secretsDir}`);
  }
  return secretsDir;
}

/**
 * Main execution
 */
function main() {
  console.log(`🔐 Generating secure secrets for ${env} environment...\n`);

  const allSecrets = [];

  for (let i = 0; i < count; i++) {
    const secrets = generateEnvironmentSecrets(`${env}${count > 1 ? `-${i + 1}` : ''}`);
    allSecrets.push(secrets);

    console.log(`Set ${i + 1}:`);
    console.log('='.repeat(50));
    Object.entries(secrets.secrets).forEach(([key, value]) => {
      console.log(`${key}: ${value}`);
    });
    console.log('');
  }

  if (outputFile) {
    ensureSecretsDir();
    const outputPath = path.join(__dirname, '..', outputFile);

    if (count === 1) {
      const envContent = formatEnvFile(allSecrets[0]);
      fs.writeFileSync(outputPath, envContent);
      console.log(`✅ Secrets written to: ${outputPath}`);
    } else {
      const jsonContent = formatJsonOutput({ sets: allSecrets });
      fs.writeFileSync(outputPath, jsonContent);
      console.log(`✅ ${count} secret sets written to: ${outputPath}`);
    }
  }

  console.log('\n⚠️  SECURITY REMINDERS:');
  console.log('1. Never commit secrets to version control');
  console.log('2. Use different secrets for each environment');
  console.log('3. Rotate secrets regularly (every 90 days recommended)');
  console.log('4. Store production secrets in a secure secrets manager');
  console.log('5. Restrict access to secrets based on principle of least privilege');

  if (env === 'production') {
    console.log('\n🚨 PRODUCTION WARNING:');
    console.log('For production environments, use:');
    console.log('- AWS Secrets Manager');
    console.log('- HashiCorp Vault');
    console.log('- Azure Key Vault');
    console.log('- Google Cloud Secret Manager');
    console.log('Never use .env files in production!');
  }
}

// Run the script
if (require.main === module) {
  main();
}

module.exports = {
  generateSecret,
  generateEnvironmentSecrets,
  formatEnvFile
};

