/**
 * Test script to verify secrets management
 */

// Simulate environment setup
process.env.NODE_ENV = 'test';
process.env.PORT = '3001';
process.env.SESSION_SECRET = 'test-session-secret-123456789012345678901234567890';
process.env.JWT_SECRET = 'test-jwt-secret-123456789012345678901234567890';
process.env.VALID_TOKENS = 'test-token-123,test-token-456';

// Load the app to test secrets validation
try {
  console.log('🔍 Testing secrets management...\n');

  // Test 1: Check required environment variables
  const requiredVars = ['NODE_ENV', 'PORT', 'SESSION_SECRET', 'JWT_SECRET'];
  const missingVars = requiredVars.filter(varName => !process.env[varName]);

  if (missingVars.length > 0) {
    console.error('❌ Missing required environment variables:', missingVars);
    process.exit(1);
  }

  console.log('✅ All required environment variables present');

  // Test 2: Validate secret strength
  const validateSecret = (secret, varName) => {
    if (!secret || secret.length < 32) {
      console.error(`❌ ${varName} is too short (min 32 chars): ${secret.length} chars`);
      return false;
    }

    const insecurePatterns = [
      'password', 'secret', 'token', 'key', '12345', 'admin',
      'test', 'demo', 'example', 'changeme', 'default'
    ];

    const lowerSecret = secret.toLowerCase();
    for (const pattern of insecurePatterns) {
      if (lowerSecret.includes(pattern)) {
        console.warn(`⚠️  ${varName} contains insecure pattern: "${pattern}"`);
        // Don't fail for warnings in test mode
      }
    }

    return true;
  };

  const sessionSecretValid = validateSecret(process.env.SESSION_SECRET, 'SESSION_SECRET');
  const jwtSecretValid = validateSecret(process.env.JWT_SECRET, 'JWT_SECRET');

  if (!sessionSecretValid || !jwtSecretValid) {
    console.error('❌ Secret validation failed');
    process.exit(1);
  }

  console.log('✅ Secrets meet strength requirements');

  // Test 3: Validate token parsing
  if (process.env.VALID_TOKENS) {
    const tokens = process.env.VALID_TOKENS.split(',');
    console.log(`✅ Valid tokens configured: ${tokens.length} tokens`);

    // Test token validation logic
    const testToken = 'test-token-123';
    if (tokens.includes(testToken)) {
      console.log('✅ Token validation logic works correctly');
    } else {
      console.error('❌ Token validation logic failed');
      process.exit(1);
    }
  }

  // Test 4: Port validation
  const port = parseInt(process.env.PORT);
  if (isNaN(port) || port < 1 || port > 65535) {
    console.error(`❌ Invalid port: ${process.env.PORT}`);
    process.exit(1);
  }

  console.log(`✅ Valid port: ${port}`);

  // Test 5: NODE_ENV validation
  const validEnvironments = ['development', 'production', 'test'];
  if (!validEnvironments.includes(process.env.NODE_ENV)) {
    console.warn(`⚠️  Unusual NODE_ENV value: ${process.env.NODE_ENV}`);
  }

  console.log(`✅ Environment: ${process.env.NODE_ENV}`);

  console.log('\n🎉 All secrets management tests passed!');
  console.log('\n📋 Summary:');
  console.log(`- Environment: ${process.env.NODE_ENV}`);
  console.log(`- Port: ${process.env.PORT}`);
  console.log(`- Session Secret: ${process.env.SESSION_SECRET ? '✓ Set' : '✗ Missing'}`);
  console.log(`- JWT Secret: ${process.env.JWT_SECRET ? '✓ Set' : '✗ Missing'}`);
  console.log(`- Valid Tokens: ${process.env.VALID_TOKENS ? '✓ Configured' : '✗ Not configured'}`);

  // Security warnings
  console.log('\n⚠️  Security Recommendations:');
  if (process.env.NODE_ENV === 'production') {
    if (process.env.SESSION_SECRET.includes('test')) {
      console.log('- Change SESSION_SECRET to a production-grade secret');
    }
    if (process.env.JWT_SECRET.includes('test')) {
      console.log('- Change JWT_SECRET to a production-grade secret');
    }
    console.log('- Use a secrets manager (AWS, HashiCorp, etc.)');
    console.log('- Enable secret rotation');
    console.log('- Configure audit logging for secret access');
  }

  process.exit(0);

} catch (error) {
  console.error('❌ Secrets test failed:', error.message);
  process.exit(1);
}

