const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

class SecretsManagerService {
  constructor() {
    this.client = new SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
  }

  async getSecret(secretName) {
    try {
      const response = await this.client.getSecretValue({ SecretId: secretName });
      return JSON.parse(response.SecretString);
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw error;
    }
  }

  async getApplicationSecrets() {
    const env = process.env.NODE_ENV || 'development';
    const secretName = `app-secrets-${env}`;

    const secrets = await this.getSecret(secretName);

    // Set secrets as environment variables
    Object.entries(secrets).forEach(([key, value]) => {
      process.env[key] = value;
    });

    return secrets;
  }
}

