// Advanced secrets management with support for multiple backends
// Supports: Environment variables, AWS Secrets Manager, Azure Key Vault, HashiCorp Vault

const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console({
      format: winston.format.simple()
    })
  ]
});

class SecretsManager {
  constructor(options = {}) {
    this.secrets = {};
    this.provider = options.provider || process.env.SECRETS_PROVIDER || 'env';
    this.options = options;
    this.initialized = false;
  }

  async init() {
    try {
      switch (this.provider.toLowerCase()) {
        case 'aws':
          await this.initAWSSecretsManager();
          break;
        case 'azure':
          await this.initAzureKeyVault();
          break;
        case 'vault':
          await this.initHashiCorpVault();
          break;
        case 'env':
        default:
          await this.initEnvironmentVariables();
          break;
      }
      this.initialized = true;
      logger.info(`Secrets manager initialized with ${this.provider} provider`);
    } catch (error) {
      logger.error('Failed to initialize secrets manager', { error: error.message });
      throw error;
    }
  }

  async initEnvironmentVariables() {
    // Load from environment variables
    this.secrets = {
      // Application
      PORT: process.env.PORT,
      NODE_ENV: process.env.NODE_ENV,
      ALLOWED_ORIGIN: process.env.ALLOWED_ORIGIN,

      // Secrets
      JWT_SECRET: process.env.JWT_SECRET,
      SESSION_SECRET: process.env.SESSION_SECRET,

      // Database
      DATABASE_URL: process.env.DATABASE_URL,

      // AWS
      AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
      AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
      AWS_REGION: process.env.AWS_REGION,

      // External APIs
      ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
      STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
      STRIPE_PUBLISHABLE_KEY: process.env.STRIPE_PUBLISHABLE_KEY,
      LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,

      // Monitoring
      SENTRY_DSN: process.env.SENTRY_DSN
    };

    // Validate required secrets
    this.validateSecrets();
  }

  async initAWSSecretsManager() {
    // AWS Secrets Manager integration
    const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

    const client = new SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1',
      credentials: {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY
      }
    });

    try {
      // Fetch secrets from AWS Secrets Manager
      const secretNames = [
        'app/secrets',
        'database/credentials',
        'api/keys'
      ];

      for (const secretName of secretNames) {
        try {
          const response = await client.getSecretValue({ SecretId: secretName });
          const secretValue = JSON.parse(response.SecretString);

          // Merge secrets
          this.secrets = { ...this.secrets, ...secretValue };
        } catch (error) {
          logger.warn(`Failed to fetch secret ${secretName}`, { error: error.message });
        }
      }

      // Still load some values from environment
      this.secrets.PORT = process.env.PORT;
      this.secrets.NODE_ENV = process.env.NODE_ENV;
      this.secrets.ALLOWED_ORIGIN = process.env.ALLOWED_ORIGIN;

      this.validateSecrets();
    } catch (error) {
      logger.error('AWS Secrets Manager initialization failed', { error: error.message });
      throw error;
    }
  }

  async initAzureKeyVault() {
    // Azure Key Vault integration
    const { SecretClient } = require('@azure/keyvault-secrets');
    const { DefaultAzureCredential } = require('@azure/identity');

    const credential = new DefaultAzureCredential();
    const vaultUrl = process.env.AZURE_KEY_VAULT_URL;

    if (!vaultUrl) {
      throw new Error('AZURE_KEY_VAULT_URL environment variable is required');
    }

    const client = new SecretClient(vaultUrl, credential);

    try {
      const secretNames = [
        'JWT-SECRET',
        'DATABASE-URL',
        'STRIPE-SECRET-KEY',
        'ANTHROPIC-API-KEY'
      ];

      for (const secretName of secretNames) {
        try {
          const secret = await client.getSecret(secretName);
          this.secrets[secretName.replace('-', '_')] = secret.value;
        } catch (error) {
          logger.warn(`Failed to fetch secret ${secretName}`, { error: error.message });
        }
      }

      // Still load some values from environment
      this.secrets.PORT = process.env.PORT;
      this.secrets.NODE_ENV = process.env.NODE_ENV;
      this.secrets.ALLOWED_ORIGIN = process.env.ALLOWED_ORIGIN;

      this.validateSecrets();
    } catch (error) {
      logger.error('Azure Key Vault initialization failed', { error: error.message });
      throw error;
    }
  }

  async initHashiCorpVault() {
    // HashiCorp Vault integration
    const vault = require('node-vault')({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN
    });

    try {
      // Read secrets from Vault
      const mountPath = process.env.VAULT_SECRET_PATH || 'secret/data/app';

      const response = await vault.read(mountPath);
      const secretData = response.data.data;

      // Merge Vault secrets
      this.secrets = { ...this.secrets, ...secretData };

      // Still load some values from environment
      this.secrets.PORT = process.env.PORT;
      this.secrets.NODE_ENV = process.env.NODE_ENV;
      this.secrets.ALLOWED_ORIGIN = process.env.ALLOWED_ORIGIN;

      this.validateSecrets();
    } catch (error) {
      logger.error('HashiCorp Vault initialization failed', { error: error.message });
      throw error;
    }
  }

  validateSecrets() {
    const requiredSecrets = [
      'JWT_SECRET',
      'PORT'
    ];

    const missingSecrets = [];

    for (const secret of requiredSecrets) {
      if (!this.secrets[secret]) {
        missingSecrets.push(secret);
      }
    }

    if (missingSecrets.length > 0) {
      const errorMsg = `Missing required secrets: ${missingSecrets.join(', ')}`;
      logger.error(errorMsg);
      throw new Error(errorMsg);
    }

    // Log which secrets are loaded (but not their values)
    const secretKeys = Object.keys(this.secrets).filter(key => 
      key.toLowerCase().includes('secret') || 
      key.toLowerCase().includes('key') ||
      key.toLowerCase().includes('token') ||
      key.toLowerCase().includes('password')
    );

    logger.info(`Loaded ${secretKeys.length} sensitive configuration values`);

    // Validate secret strength for critical secrets
    this.validateSecretStrength();
  }

  validateSecretStrength() {
    // Validate JWT secret strength
    if (this.secrets.JWT_SECRET) {
      const jwtSecret = this.secrets.JWT_SECRET;
      if (jwtSecret.length < 32) {
        logger.warn('JWT_SECRET is less than 32 characters - consider using a stronger secret');
      }

      // Check for common weak secrets
      const weakPatterns = [
        'secret',
        'password',
        '123456',
        'changeme',
        'admin'
      ];

      for (const pattern of weakPatterns) {
        if (jwtSecret.toLowerCase().includes(pattern)) {
          logger.warn(`JWT_SECRET contains common weak pattern: ${pattern}`);
        }
      }
    }
  }

  get(secretName) {
    if (!this.initialized) {
      throw new Error('Secrets manager not initialized. Call init() first.');
    }

    const value = this.secrets[secretName];

    if (!value && this.options.throwOnMissing !== false) {
      logger.error(`Attempted to access missing secret: ${secretName}`);
      throw new Error(`Secret not found: ${secretName}`);
    }

    // Log access to sensitive secrets (without the value)
    if (secretName.toLowerCase().includes('secret') || 
        secretName.toLowerCase().includes('key') ||
        secretName.toLowerCase().includes('token') ||
        secretName.toLowerCase().includes('password')) {
      logger.debug(`Accessed sensitive secret: ${secretName}`);
    }

    return value;
  }

  async rotateSecret(secretName) {
    logger.info(`Initiating rotation for secret: ${secretName}`);

    // Implement secret rotation logic based on provider
    switch (this.provider.toLowerCase()) {
      case 'aws':
