        break;
      case 'vault':
        // HashiCorp Vault rotation
        break;
      default:
        logger.warn(`Manual rotation required for ${secretName} with env provider`);
        break;
    }
  }

  getAll() {
    // Return a safe copy without sensitive values for debugging
    const safeCopy = { ...this.secrets };

    // Redact sensitive values
    const sensitiveKeys = Object.keys(safeCopy).filter(key => 
      key.toLowerCase().includes('secret') || 
      key.toLowerCase().includes('key') ||
      key.toLowerCase().includes('token') ||
      key.toLowerCase().includes('password')
    );

    for (const key of sensitiveKeys) {
