#!/usr/bin/env node

/**
 * Secret validation script
 * Validates that all required secrets are present and meet security requirements
 */

const crypto = require('crypto');
const { getInstance } = require('../config/secrets');

async function validateSecrets() {
  console.log('🔐 Starting secrets validation...\n');

  try {
    // Initialize secrets manager
    const secretsManager = getInstance({
      provider: process.env.SECRETS_PROVIDER || 'env',
      throwOnMissing: false
    });

    await secretsManager.init();

    const secrets = secretsManager.getAll();
    const validationResults = [];

    console.log('📊 Secret Validation Results');
    console.log('=' .repeat(50));

    // 1. Check for required secrets
    const requiredSecrets = ['JWT_SECRET', 'PORT'];
    for (const secret of requiredSecrets) {
      const hasSecret = !!secrets[secret];
      validationResults.push({
        secret,
        status: hasSecret ? '✅ PRESENT' : '❌ MISSING',
        critical: true
      });
    }

    // 2. Validate JWT secret strength
    if (secrets.JWT_SECRET && secrets.JWT_SECRET !== '[REDACTED]') {
      const jwtSecret = secrets.JWT_SECRET;
      const lengthOk = jwtSecret.length >= 32;
      const entropy = calculateEntropy(jwtSecret);
      const strongEntropy = entropy > 3.5; // bits per character

      let strength = '✅ STRONG';
      if (!lengthOk) strength = '⚠️ WEAK (too short)';
      else if (!strongEntropy) strength = '⚠️ WEAK (low entropy)';

      validationResults.push({
        secret: 'JWT_SECRET_STRENGTH',
        status: strength,
        details: `Length: ${jwtSecret.length} chars, Entropy: ${entropy.toFixed(2)} bits/char`
      });
    }

    // 3. Check for weak/common secrets
    const weakPatterns = [
      { pattern: 'secret', type: 'common word' },
      { pattern: 'password', type: 'common word' },
      { pattern: '123456', type: 'sequential' },
      { pattern: 'admin', type: 'default' },
      { pattern: 'changeme', type: 'default' },
      { pattern: 'test', type: 'test value' }
    ];

    for (const [key, value] of Object.entries(secrets)) {
      if (value === '[REDACTED]') continue;

      for (const weak of weakPatterns) {
        if (value.toLowerCase().includes(weak.pattern)) {
          validationResults.push({
            secret: key,
            status: '⚠️ WEAK PATTERN',
            details: `Contains "${weak.pattern}" (${weak.type})`
          });
        }
      }
    }

    // 4. Check database URL security
    if (secrets.DATABASE_URL && secrets.DATABASE_URL !== '[REDACTED]') {
      const dbUrl = secrets.DATABASE_URL;
      const hasSSL = dbUrl.includes('sslmode=require') || dbUrl.includes('ssl=true');

      validationResults.push({
        secret: 'DATABASE_SSL',
        status: hasSSL ? '✅ SSL ENABLED' : '⚠️ SSL NOT ENFORCED',
        critical: true
      });

      // Check for default ports
      if (dbUrl.includes(':5432/') && !dbUrl.includes('localhost')) {
        validationResults.push({
          secret: 'DATABASE_PORT',
          status: '⚠️ DEFAULT PORT',
          details: 'Using default PostgreSQL port 5432'
        });
      }
    }

    // 5. Validate AWS credentials format
    if (secrets.AWS_ACCESS_KEY_ID && secrets.AWS_ACCESS_KEY_ID !== '[REDACTED]') {
      const awsKey = secrets.AWS_ACCESS_KEY_ID;
      const isValidFormat = /^AKIA[0-9A-Z]{16}$/.test(awsKey);

      validationResults.push({
        secret: 'AWS_KEY_FORMAT',
        status: isValidFormat ? '✅ VALID FORMAT' : '❌ INVALID FORMAT',
        details: `Key: ${awsKey.substring(0, 8)}...`
      });
    }

    // 6. Check for canary values (from .env.test)
    const canaryValues = [
      'CANARY-db-secret',
      'CANARY-aws-secret-key',
      'CANARY-api-key',
      'CANARY-stripe-key',
      'CANARY-logfire-token'
    ];

    for (const [key, value] of Object.entries(secrets)) {
      if (value === '[REDACTED]') continue;

      for (const canary of canaryValues) {
        if (value.includes(canary)) {
          validationResults.push({
            secret: key,
            status: '🚨 CANARY VALUE DETECTED',
            details: 'Using test/canary value in production!',
            critical: true
          });
        }
      }
    }

    // 7. Environment validation
    validationResults.push({
      secret: 'NODE_ENV',
      status: secrets.NODE_ENV === 'production' ? '✅ PRODUCTION' : '⚠️ DEVELOPMENT',
      details: `Current: ${secrets.NODE_ENV || 'not set'}`
    });

    // Print results
    let criticalIssues = 0;

    for (const result of validationResults) {
      let output = `${result.status} - ${result.secret}`;
      if (result.details) {
        output += ` (${result.details})`;
      }
      console.log(output);

      if (result.status.includes('❌') || result.status.includes('🚨')) {
        criticalIssues++;
      }
    }

    console.log('\n' + '=' .repeat(50));
    console.log(`Validation complete. Loaded ${Object.keys(secrets).length} configuration values.`);

    if (criticalIssues > 0) {
      console.log(`\n🚨 Found ${criticalIssues} CRITICAL issues that must be addressed!`);
      process.exit(1);
    } else {
      console.log('\n✅ All secrets validated successfully!');
    }

    // Generate security report
    generateSecurityReport(secrets, validationResults);

  } catch (error) {
    console.error('❌ Secret validation failed:', error.message);
    process.exit(1);
  }
}

function calculateEntropy(str) {
  // Calculate Shannon entropy of a string
  const len = str.length;
  const frequencies = {};

  for (const char of str) {
    frequencies[char] = (frequencies[char] || 0) + 1;
  }

  let entropy = 0;
  for (const freq of Object.values(frequencies)) {
    const probability = freq / len;
    entropy -= probability * Math.log2(probability);
  }

  return entropy;
}

function generateSecurityReport(secrets, validationResults) {
  const report = {
    timestamp: new Date().toISOString(),
    environment: secrets.NODE_ENV || 'unknown',
    secretsProvider: process.env.SECRETS_PROVIDER || 'env',
    validationResults: validationResults.map(r => ({
      secret: r.secret,
      status: r.status,
      critical: !!r.critical
    })),
    summary: {
      totalSecrets: Object.keys(secrets).length,
      criticalIssues: validationResults.filter(r => 
        r.status.includes('❌') || r.status.includes('🚨')
      ).length,
      warnings: validationResults.filter(r => 
        r.status.includes('⚠️')
      ).length,
      passed: validationResults.filter(r => 
        r.status.includes('✅')
      ).length
    },
    recommendations: []
  };

  // Add recommendations based on findings
  const hasCanary = validationResults.some(r => r.status.includes('CANARY'));
  if (hasCanary) {
    report.recommendations.push({
      priority: 'CRITICAL',
      action: 'Replace all canary/trap values with real production secrets',
      timeline: 'Immediately'
    });
  }

  const weakJWT = validationResults.some(r => 
    r.secret === 'JWT_SECRET_STRENGTH' && r.status.includes('WEAK')
  );
  if (weakJWT) {
    report.recommendations.push({
      priority: 'HIGH',
      action: 'Generate a stronger JWT secret (min 32 chars, high entropy)',
      timeline: 'Next deployment'
    });
  }

  if (secrets.NODE_ENV !== 'production') {
    report.recommendations.push({
      priority: 'MEDIUM',
      action: 'Set NODE_ENV=production for production deployments',
      timeline: 'Next deployment'
    });
  }

  // Save report to file
  const fs = require('fs');
  const reportFile = `security-report-${new Date().toISOString().split('T')[0]}.json`;
  fs.writeFileSync(`logs/${reportFile}`, JSON.stringify(report, null, 2));

  console.log(`\n📋 Security report saved to: logs/${reportFile}`);
}

// Run validation
if (require.main === module) {
  validateSecrets().catch(error => {
    console.error('Fatal error during validation:', error);
    process.exit(1);
  });
}

module.exports = { validateSecrets };

